mapper.select:
SELECT 'EVENT' AS kind, e.underpass_id, u.name AS underpass_name, e.event_type, e.risk_level,
       e.risk_score_at_event, NULL::display_message_type AS message_type, e.operator_id, e.created_at
  FROM underpass_event e
  JOIN underpass u ON u.id = e.underpass_id
 WHERE e.underpass_id = #{underpassId}
   AND FALSE
   AND e.created_at >= #{startAt}
   AND e.created_at < #{endAt}
UNION ALL
SELECT 'DISPLAY' AS kind, d.underpass_id, u.name AS underpass_name, NULL::underpass_event_type,
       NULL::risk_level, NULL::DECIMAL(4,3), d.message_type, d.operator_id, d.created_at
  FROM display_log d
  JOIN underpass u ON u.id = d.underpass_id
 WHERE d.underpass_id = #{underpassId}
   AND FALSE
   AND d.created_at >= #{startAt}
   AND d.created_at < #{endAt}
 ORDER BY created_at DESC
